const { query, location, gl, hl, num, start } = $.input;
if (!query) throw new Error('query is required');

const params = { engine: 'google', q: query };
if (location) params.location = location;
if (gl) params.gl = gl;
if (hl) params.hl = hl;
if (num && num !== 10) params.num = String(num);
if (start) params.start = String(start);

return { params };

const resp = $.steps.search.response || {};
const info = resp.search_information || {};
const organic = (resp.organic_results || []).map(r => ({
  position: r.position,
  title: r.title || '',
  link: r.link || '',
  snippet: r.snippet || '',
  displayedLink: r.displayed_link || ''
}));

const localResults = (resp.local_results?.places || []).map(p => ({
  title: p.title || '',
  type: p.type || '',
  address: p.address || '',
  rating: p.rating || null,
  reviews: p.reviews || 0
}));

const knowledgeGraph = resp.knowledge_graph ? {
  title: resp.knowledge_graph.title || '',
  type: resp.knowledge_graph.type || '',
  description: resp.knowledge_graph.description || ''
} : null;

return {
  query: $.input.query,
  totalResults: info.total_results || 0,
  organicResults: organic,
  localResults,
  knowledgeGraph,
  relatedSearches: (resp.related_searches || []).map(r => r.query || ''),
  summary: `Found ${organic.length} organic result${organic.length === 1 ? '' : 's'} for "${$.input.query}"${info.total_results ? ` (${info.total_results.toLocaleString()} total)` : ''}`
};
